"""Practice sets for A Level Food Science and Nutrition (Upper Sixth): Food Engineering & Preservation Technology,
Post-Harvest Commodity Technology, and Food Quality Assurance & Legislation. One set per lesson, in the order of the
lessons file of the same name. Numbers are teaching data."""

from .dsl import *  # noqa: F403

COURSE = ("food-and-nutrition", "upper-sixth")

M1 = "Food Engineering & Preservation Technology"
M2 = "Post-Harvest Commodity Technology"
M3 = "Food Quality Assurance & Legislation"

_POS = [2, 0, 3, 1, 1, 3, 0, 2, 3, 1, 2, 0, 0, 2, 1, 3, 1, 2, 0, 3, 3, 0, 1, 2, 2, 3, 1, 0, 0, 1, 3, 2]
_COUNT = [0]


def mc(prompt, right, wrongs, steps, concept, skill, hint, feedback="", diagram="", alt=""):
    """Multiple choice; wrongs = [(text, why) x3]. The correct option is placed by a fixed rotation so that A, B, C
    and D are used about equally often."""
    pos = _POS[_COUNT[0] % len(_POS)]
    _COUNT[0] += 1
    opts = [C(w, why=y) for w, y in wrongs]
    opts.insert(pos, C(right, correct=True))
    if isinstance(steps, str):
        steps = [S("Reasoning", text=steps)]
    return MC(prompt, opts, steps=steps, concept=concept, skill=skill, hint=hint, feedback=feedback,
              diagram=diagram, diagram_alt=alt)


def num(prompt, answer, steps, concept, skill, hint, unit="", tolerance=0, diagram="", alt=""):
    if isinstance(steps, str):
        steps = [S("Working", text=steps)]
    return NUM(prompt, answer, steps=steps, concept=concept, skill=skill, hint=hint, unit=unit,
               tolerance=tolerance, diagram=diagram, diagram_alt=alt)


